import { useMemo, useState } from 'react';
import { MapPinned, Sun, Moon } from 'lucide-react';
import { FaGithub } from 'react-icons/fa6';
import type {
  TripConfig, DayPlan, PlanMode, Hotel, ContentModule, BudgetSummary,
} from './contracts';
import { TripInput } from '@/regions/trip-input';
import { DailyPlan } from '@/regions/daily-plan';
import { BudgetExport } from '@/regions/budget-export';
import {
  DEFAULT_CONFIG, AI_PLAN, SCRATCH_PLAN,
} from '@/mock/data';

type Page = 'trip-input' | 'daily-plan' | 'budget-export';

const AVATAR = 'https://s1-imfile.feishucdn.com/static-resource/v1/v3_0012n_9ac8a84c-f04d-4b4d-bc0b-06d0bb3d44dg~?image_size=noop&cut_type=&quality=&format=png&sticker_format=.webp';

export default function App() {
  const [page, setPage] = useState<Page>('trip-input');
  const [config, setConfig] = useState<TripConfig>(DEFAULT_CONFIG);
  const [mode, setMode] = useState<PlanMode>('ai');
  const [aiPlan, setAiPlan] = useState<DayPlan[]>(AI_PLAN);
  const [scratchPlan, setScratchPlan] = useState<DayPlan[]>(SCRATCH_PLAN);
  const [hotel, setHotel] = useState<Hotel | null>(null);
  const [isDark, setIsDark] = useState(false);

  const plan = mode === 'ai' ? aiPlan : scratchPlan;
  const setPlan = mode === 'ai' ? setAiPlan : setScratchPlan;

  const budget: BudgetSummary = useMemo(() => {
    const modules = plan.flatMap((day) => day.slots.map((slot) => slot.module).filter((mod): mod is ContentModule => !!mod));
    const moduleCost = (categories: ContentModule['category'][]) => modules
      .filter((mod) => categories.includes(mod.category))
      .reduce((sum, mod) => sum + mod.price, 0);
    const hotelNightly = hotel ? Number(hotel.priceRange.match(/\d+/)?.[0] ?? 0) : 650;
    const items: BudgetSummary['items'] = [
      { category: 'transport', label: '交通', amount: 800 + moduleCost(['transport']) },
      { category: 'hotel', label: '住宿', amount: hotelNightly * Math.max(config.days - 1, 1) },
      { category: 'food', label: '餐饮', amount: 500 + moduleCost(['food']) },
      { category: 'ticket', label: '门票 / 体验', amount: 350 + moduleCost(['scenery', 'shop', 'activity']) },
    ];
    const total = items.reduce((sum, item) => sum + item.amount, 0);
    const limit = config.budgetRange[1] || 5000;
    return { total, limit, overBudget: total > limit, items };
  }, [plan, hotel, config.days, config.budgetRange]);

  const handleStart = (cfg: TripConfig) => {
    setConfig(cfg);
    setPage('daily-plan');
  };

  const handleInsert = (dayIdx: number, slotId: string, modu: ContentModule) => {
    setPlan((prev) => prev.map((d, i) => (i !== dayIdx ? d : {
      ...d,
      slots: d.slots.map((s) => (s.id === slotId ? { ...s, module: modu } : s)),
    })));
  };

  const handleRemove = (dayIdx: number, slotId: string) => {
    setPlan((prev) => prev.map((d, i) => (i !== dayIdx ? d : {
      ...d,
      slots: d.slots.map((s) => (s.id === slotId ? { ...s, module: null, routeFromPrev: undefined, routeWarning: undefined } : s)),
    })));
  };

  const toggleTheme = () => {
    window.__toggleDarkMode?.();
    setIsDark((v) => !v);
  };

  return (
    <div data-source="src/index.tsx:72:4" className="min-h-screen bg-background text-foreground font-[PingFang_SC,'Noto_Sans_SC',sans-serif] antialiased">
      {/* 柔雾装饰背景 */}
      <div data-source="src/index.tsx:74:6" aria-hidden className="pointer-events-none fixed inset-0 overflow-hidden">
        <div data-source="src/index.tsx:75:8" className="absolute -top-40 -right-32 size-[520px] rounded-full bg-primary/10 blur-3xl" />
        <div data-source="src/index.tsx:76:8" className="absolute top-1/3 -left-40 size-[440px] rounded-full bg-accent/10 blur-3xl" />
      </div>

      {/* 顶部品牌栏 */}
      <header data-source="src/index.tsx:80:6" className="sticky top-0 z-30 border-b border-border bg-background/80 backdrop-blur-md">
        <div data-source="src/index.tsx:81:8" className="mx-auto flex h-16 max-w-[1280px] items-center justify-between px-6">
          <button data-source="src/index.tsx:82:10"
            type="button"
            onClick={() => setPage('trip-input')}
            className="flex items-center gap-2.5 rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            <span data-source="src/index.tsx:87:12" className="flex size-9 items-center justify-center rounded-full bg-primary text-primary-foreground">
              <MapPinned data-source="src/index.tsx:88:14" size={20} strokeWidth={1.75} />
            </span>
            <span data-source="src/index.tsx:90:12" className="text-lg font-bold tracking-tight">悠行 · Wander</span>
          </button>

          <div data-source="src/index.tsx:93:10" className="flex items-center gap-3">
            <a data-source="src/index.tsx:94:12"
              href="https://github.com"
              target="_blank"
              rel="noreferrer"
              className="hidden size-9 items-center justify-center rounded-full text-muted-foreground transition hover:bg-secondary hover:text-foreground sm:flex focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              aria-label="GitHub"
            >
              <FaGithub data-source="src/index.tsx:101:14" className="size-[18px]" />
            </a>
            <button data-source="src/index.tsx:103:12"
              type="button"
              onClick={toggleTheme}
              aria-label="切换主题"
              className="flex size-9 items-center justify-center rounded-full text-muted-foreground transition hover:bg-secondary hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              {isDark ? <Sun data-source="src/index.tsx:109:24" size={18} strokeWidth={1.75} /> : <Moon data-source="src/index.tsx:109:63" size={18} strokeWidth={1.75} />}
            </button>
            <img data-source="src/index.tsx:111:12" src={AVATAR} alt="章竞以" className="size-9 rounded-full border border-border object-cover" />
          </div>
        </div>
      </header>

      <main data-source="src/index.tsx:116:6" className="relative z-10">
        {page === 'trip-input' && <TripInput data-source="src/index.tsx:117:34" onStart={handleStart} />}
        {page === 'daily-plan' && (
          <DailyPlan data-source="src/index.tsx:119:10"
            config={config}
            plan={plan}
            mode={mode}
            hotel={hotel}
            budget={budget}
            onModeChange={setMode}
            onInsertModule={handleInsert}
            onRemoveModule={handleRemove}
            onSelectHotel={setHotel}
            onGoBudget={() => setPage('budget-export')}
          />
        )}
        {page === 'budget-export' && (
          <BudgetExport data-source="src/index.tsx:133:10"
            budget={budget}
            config={config}
            onBack={() => setPage('daily-plan')}
          />
        )}
      </main>
    </div>
  );
}
