import { useState, useRef, useEffect } from 'react';
import { Download, Smartphone, Share2, CheckCircle, LoaderCircle, MapPin, CalendarDays } from 'lucide-react';
import type { BudgetSummary, TripConfig } from '../../contracts';

type ExportState = 'idle' | 'loading' | 'done';

function money(n: number) {
  return '¥' + n.toLocaleString('zh-CN');
}

interface ExportPanelProps {
  budget: BudgetSummary;
  config: TripConfig;
}

export function ExportPanel({ budget, config }: ExportPanelProps) {
  const [h5State, setH5State] = useState<ExportState>('idle');
  const [shareState, setShareState] = useState<ExportState>('idle');

  const timers = useRef<number[]>([]);
  useEffect(() => {
    return () => {
      timers.current.forEach((t) => window.clearTimeout(t));
    };
  }, []);

  function run(setter: (s: ExportState) => void) {
    setter('loading');
    const t = window.setTimeout(() => setter('done'), 1000);
    timers.current.push(t);
  }

  const previewImg =
    'https://images.pexels.com/photos/1271619/pexels-photo-1271619.jpeg?auto=compress&cs=tinysrgb&w=600';

  return (
    <aside data-source="src/regions/budget-export/ExportPanel.tsx:37:4" className="lg:sticky lg:top-6 flex flex-col gap-5">
      {/* long-image export preview thumbnail */}
      <div data-source="src/regions/budget-export/ExportPanel.tsx:39:6" className="bg-card rounded-[20px] border border-border p-5">
        <div data-source="src/regions/budget-export/ExportPanel.tsx:40:8" className="flex items-center justify-between">
          <h3 data-source="src/regions/budget-export/ExportPanel.tsx:41:10" className="text-base font-bold tracking-tight text-foreground">长图导出预览</h3>
          <span data-source="src/regions/budget-export/ExportPanel.tsx:42:10" className="text-xs text-muted-foreground">竖版长图</span>
        </div>

        <div data-source="src/regions/budget-export/ExportPanel.tsx:45:8" className="mt-4 mx-auto w-full max-w-[220px] overflow-hidden rounded-[16px] border border-border bg-card shadow-sm">
          <div data-source="src/regions/budget-export/ExportPanel.tsx:46:10" className="aspect-[16/10] overflow-hidden">
            <img data-source="src/regions/budget-export/ExportPanel.tsx:47:12"
              src={previewImg}
              alt="行程封面"
              className="h-full w-full object-cover"
            />
          </div>
          <div data-source="src/regions/budget-export/ExportPanel.tsx:53:10" className="p-3.5">
            <div data-source="src/regions/budget-export/ExportPanel.tsx:54:12" className="flex items-center gap-1.5 text-foreground">
              <MapPin data-source="src/regions/budget-export/ExportPanel.tsx:55:14" size={14} strokeWidth={1.75} className="text-primary" />
              <p data-source="src/regions/budget-export/ExportPanel.tsx:56:14" className="text-sm font-semibold tracking-tight truncate">{config.destination}</p>
            </div>
            <div data-source="src/regions/budget-export/ExportPanel.tsx:58:12" className="mt-1 flex items-center gap-1.5 text-xs text-muted-foreground">
              <CalendarDays data-source="src/regions/budget-export/ExportPanel.tsx:59:14" size={13} strokeWidth={1.75} />
              <span data-source="src/regions/budget-export/ExportPanel.tsx:60:14">
                {config.days} 天 · {config.startDate} 起
              </span>
            </div>

            <div data-source="src/regions/budget-export/ExportPanel.tsx:65:12" className="mt-3 space-y-1.5">
              {budget.items.slice(0, 4).map((it) => (
                <div data-source="src/regions/budget-export/ExportPanel.tsx:67:16" key={it.category} className="flex items-center justify-between text-xs">
                  <span data-source="src/regions/budget-export/ExportPanel.tsx:68:18" className="text-muted-foreground truncate">{it.label}</span>
                  <span data-source="src/regions/budget-export/ExportPanel.tsx:69:18" className="font-medium text-foreground">{money(it.amount)}</span>
                </div>
              ))}
            </div>

            <div data-source="src/regions/budget-export/ExportPanel.tsx:74:12" className="mt-3 flex items-center justify-between border-t border-border pt-2.5">
              <span data-source="src/regions/budget-export/ExportPanel.tsx:75:14" className="text-xs text-muted-foreground">预算合计</span>
              <span data-source="src/regions/budget-export/ExportPanel.tsx:76:14" className="text-sm font-bold tracking-tight text-primary">
                {money(budget.total)}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* export actions */}
      <div data-source="src/regions/budget-export/ExportPanel.tsx:85:6" className="bg-card rounded-[20px] border border-border p-5">
        <h3 data-source="src/regions/budget-export/ExportPanel.tsx:86:8" className="text-base font-bold tracking-tight text-foreground">导出与分享</h3>
        <p data-source="src/regions/budget-export/ExportPanel.tsx:87:8" className="mt-1 text-xs text-muted-foreground">生成可分享的行程内容</p>

        <div data-source="src/regions/budget-export/ExportPanel.tsx:89:8" className="mt-4 flex flex-col gap-3">
          <ExportButton data-source="src/regions/budget-export/ExportPanel.tsx:90:10"
            state={h5State}
            onRun={() => run(setH5State)}
            idleLabel="导出 H5 页面"
            doneLabel="H5 已生成"
            IdleIcon={Smartphone}
            primary
          />
          <ExportButton data-source="src/regions/budget-export/ExportPanel.tsx:98:10"
            state={shareState}
            onRun={() => run(setShareState)}
            idleLabel="分享给同行伙伴"
            doneLabel="分享链接已就绪"
            IdleIcon={Share2}
          />
        </div>

        <p data-source="src/regions/budget-export/ExportPanel.tsx:107:8" className="mt-4 flex items-center gap-1.5 text-xs text-muted-foreground">
          <Download data-source="src/regions/budget-export/ExportPanel.tsx:108:10" size={13} strokeWidth={1.75} />
          导出内容将包含完整每日行程与预算明细
        </p>
      </div>
    </aside>
  );
}

interface ExportButtonProps {
  state: ExportState;
  onRun: () => void;
  idleLabel: string;
  doneLabel: string;
  IdleIcon: typeof Download;
  primary?: boolean;
}

function ExportButton({ state, onRun, idleLabel, doneLabel, IdleIcon, primary }: ExportButtonProps) {
  const base =
    'flex items-center justify-center gap-2 rounded-full h-12 px-6 font-semibold transition active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:active:scale-100';

  if (state === 'done') {
    return (
      <div data-source="src/regions/budget-export/ExportPanel.tsx:131:6" className="flex flex-col gap-2">
        <div data-source="src/regions/budget-export/ExportPanel.tsx:132:8" className="flex items-center justify-center gap-2 rounded-full h-12 px-6 font-semibold bg-[#5C8A6B]/10 text-[#5C8A6B]">
          <CheckCircle data-source="src/regions/budget-export/ExportPanel.tsx:133:10" size={18} strokeWidth={1.75} />
          {doneLabel}
        </div>
        <button data-source="src/regions/budget-export/ExportPanel.tsx:136:8"
          type="button"
          onClick={onRun}
          className="text-xs font-medium text-accent hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded"
        >
          再次导出
        </button>
      </div>
    );
  }

  const loading = state === 'loading';
  return (
    <button data-source="src/regions/budget-export/ExportPanel.tsx:149:4"
      type="button"
      onClick={onRun}
      disabled={loading}
      className={`${base} ${
        primary
          ? 'bg-primary text-primary-foreground hover:brightness-105'
          : 'bg-secondary text-secondary-foreground hover:brightness-105'
      } ${loading ? 'opacity-90' : ''}`}
    >
      {loading ? (
        <>
          <LoaderCircle data-source="src/regions/budget-export/ExportPanel.tsx:161:10" size={18} strokeWidth={1.75} className="animate-spin" />
          导出中…
        </>
      ) : (
        <>
          <IdleIcon data-source="src/regions/budget-export/ExportPanel.tsx:166:10" size={18} strokeWidth={1.75} />
          {idleLabel}
        </>
      )}
    </button>
  );
}
