import { MapPin, Clock, AlertCircle, Trash2, Replace, TrainFront, Car, Plus } from 'lucide-react';
import type { DayPlan, Slot } from '../../contracts';
import { cn, VerifyChip, CategoryBadge, formatStay, CATEGORY_TEXT } from './ui';

interface TimelineProps {
  day: DayPlan;
  dayIdx: number;
  onRemove: (slotId: string) => void;
  onOpenInsert: (slot: Slot) => void;
}

export function Timeline({ day, onRemove, onOpenInsert }: TimelineProps) {
  return (
    <div data-source="src/regions/daily-plan/Timeline.tsx:14:4" className="relative">
      {day.slots.map((slot, i) => (
        <SlotRow data-source="src/regions/daily-plan/Timeline.tsx:16:8"
          key={slot.id}
          slot={slot}
          isLast={i === day.slots.length - 1}
          onRemove={() => onRemove(slot.id)}
          onOpenInsert={() => onOpenInsert(slot)}
        />
      ))}
    </div>
  );
}

function SlotRow({
  slot,
  isLast,
  onRemove,
  onOpenInsert,
}: {
  slot: Slot;
  isLast: boolean;
  onRemove: () => void;
  onOpenInsert: () => void;
}) {
  const filled = !!slot.module;
  const isIntercity = slot.type === 'intercity';

  return (
    <div data-source="src/regions/daily-plan/Timeline.tsx:43:4" className="relative flex gap-4 pb-6">
      {/* 路线线 + 节点 */}
      <div data-source="src/regions/daily-plan/Timeline.tsx:45:6" className="relative flex w-3 shrink-0 flex-col items-center">
        <div data-source="src/regions/daily-plan/Timeline.tsx:46:8"
          className={cn(
            'z-10 mt-1.5 size-3 shrink-0 rounded-full',
            filled ? 'bg-primary' : 'border border-border bg-card',
          )}
        />
        {!isLast && <div data-source="src/regions/daily-plan/Timeline.tsx:52:20" className="absolute top-1.5 h-full w-px bg-border" />}
      </div>

      <div data-source="src/regions/daily-plan/Timeline.tsx:55:6" className="min-w-0 flex-1">
        <div data-source="src/regions/daily-plan/Timeline.tsx:56:8" className="mb-2 flex items-center gap-2">
          <span data-source="src/regions/daily-plan/Timeline.tsx:57:10" className="text-xs uppercase tracking-wide text-muted-foreground">{slot.label}</span>
          {isIntercity && (
            <span data-source="src/regions/daily-plan/Timeline.tsx:59:12" className="inline-flex items-center gap-1 rounded-full bg-[#4A7BA6]/10 px-2 py-0.5 text-xs text-[#4A7BA6]">
              <TrainFront data-source="src/regions/daily-plan/Timeline.tsx:60:14" strokeWidth={1.75} className="size-3.5" />
              跨城交通
            </span>
          )}
        </div>

        {/* 与上一模块的路线信息 */}
        {slot.routeFromPrev && filled && (
          <div data-source="src/regions/daily-plan/Timeline.tsx:68:10" className="mb-2 inline-flex items-center gap-1 text-xs text-muted-foreground">
            <Car data-source="src/regions/daily-plan/Timeline.tsx:69:12" strokeWidth={1.75} className="size-3.5" />
            {slot.routeFromPrev}
          </div>
        )}
        {slot.routeWarning && (
          <div data-source="src/regions/daily-plan/Timeline.tsx:74:10" className="mb-2 flex items-start gap-1.5 rounded-xl bg-primary/10 px-3 py-2 text-xs text-primary">
            <AlertCircle data-source="src/regions/daily-plan/Timeline.tsx:75:12" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
            <span data-source="src/regions/daily-plan/Timeline.tsx:76:12">{slot.routeWarning}</span>
          </div>
        )}

        {filled ? (
          isIntercity ? (
            <IntercityCard data-source="src/regions/daily-plan/Timeline.tsx:82:12" slot={slot} onRemove={onRemove} onOpenInsert={onOpenInsert} />
          ) : (
            <ModuleCard data-source="src/regions/daily-plan/Timeline.tsx:84:12" slot={slot} onRemove={onRemove} onOpenInsert={onOpenInsert} />
          )
        ) : (
          <EmptySlot data-source="src/regions/daily-plan/Timeline.tsx:87:10" onOpenInsert={onOpenInsert} />
        )}
      </div>
    </div>
  );
}

function ModuleCard({
  slot,
  onRemove,
  onOpenInsert,
}: {
  slot: Slot;
  onRemove: () => void;
  onOpenInsert: () => void;
}) {
  const m = slot.module!;
  return (
    <div data-source="src/regions/daily-plan/Timeline.tsx:105:4" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
      <div data-source="src/regions/daily-plan/Timeline.tsx:106:6" className="flex gap-4">
        {m.image && (
          <div data-source="src/regions/daily-plan/Timeline.tsx:108:10" className="hidden w-36 shrink-0 overflow-hidden rounded-[16px] sm:block">
            <img data-source="src/regions/daily-plan/Timeline.tsx:109:12" src={m.image} alt={m.name} className="size-full object-cover" />
          </div>
        )}
        <div data-source="src/regions/daily-plan/Timeline.tsx:112:8" className="min-w-0 flex-1">
          <div data-source="src/regions/daily-plan/Timeline.tsx:113:10" className="flex items-start justify-between gap-2">
            <h4 data-source="src/regions/daily-plan/Timeline.tsx:114:12" className="text-base font-semibold text-foreground">{m.name}</h4>
            <VerifyChip data-source="src/regions/daily-plan/Timeline.tsx:115:12" status={m.verify} />
          </div>

          <div data-source="src/regions/daily-plan/Timeline.tsx:118:10" className="mt-2 flex flex-wrap items-center gap-2">
            <CategoryBadge data-source="src/regions/daily-plan/Timeline.tsx:119:12" label={CATEGORY_TEXT[m.category]} />
            <span data-source="src/regions/daily-plan/Timeline.tsx:120:12" className="inline-flex items-center gap-1 text-xs text-muted-foreground">
              <Clock data-source="src/regions/daily-plan/Timeline.tsx:121:14" strokeWidth={1.75} className="size-3.5" />
              建议停留 {formatStay(m.stayMinutes)}
            </span>
            {m.price > 0 && <span data-source="src/regions/daily-plan/Timeline.tsx:124:28" className="text-xs font-semibold text-foreground">¥{m.price}/人</span>}
          </div>

          <p data-source="src/regions/daily-plan/Timeline.tsx:127:10" className="mt-2 text-sm text-muted-foreground">{m.reason}</p>

          <div data-source="src/regions/daily-plan/Timeline.tsx:129:10" className="mt-2 flex items-start gap-1 text-xs text-muted-foreground">
            <MapPin data-source="src/regions/daily-plan/Timeline.tsx:130:12" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
            {m.address ? (
              <span data-source="src/regions/daily-plan/Timeline.tsx:132:14">{m.address}</span>
            ) : (
              <span data-source="src/regions/daily-plan/Timeline.tsx:134:14" className="text-primary">地址待确认，无法精确计算路线</span>
            )}
          </div>

          <p data-source="src/regions/daily-plan/Timeline.tsx:138:10" className="mt-1.5 text-xs text-muted-foreground">来源：{m.source}</p>

          {m.risk && (
            <div data-source="src/regions/daily-plan/Timeline.tsx:141:12" className="mt-2 flex items-start gap-1 rounded-xl bg-primary/10 px-2.5 py-1.5 text-xs text-primary">
              <AlertCircle data-source="src/regions/daily-plan/Timeline.tsx:142:14" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
              <span data-source="src/regions/daily-plan/Timeline.tsx:143:14">{m.risk}</span>
            </div>
          )}

          <div data-source="src/regions/daily-plan/Timeline.tsx:147:10" className="mt-3 flex items-center gap-2">
            <button data-source="src/regions/daily-plan/Timeline.tsx:148:12"
              type="button"
              onClick={onOpenInsert}
              className="inline-flex items-center gap-1 rounded-full bg-muted px-3 py-1.5 text-xs font-medium text-foreground transition hover:brightness-95 active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              <Replace data-source="src/regions/daily-plan/Timeline.tsx:153:14" strokeWidth={1.75} className="size-3.5" />
              替换
            </button>
            <button data-source="src/regions/daily-plan/Timeline.tsx:156:12"
              type="button"
              onClick={onRemove}
              className="inline-flex items-center gap-1 rounded-full bg-muted px-3 py-1.5 text-xs font-medium text-muted-foreground transition hover:text-primary active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              <Trash2 data-source="src/regions/daily-plan/Timeline.tsx:161:14" strokeWidth={1.75} className="size-3.5" />
              删除
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function IntercityCard({
  slot,
  onRemove,
  onOpenInsert,
}: {
  slot: Slot;
  onRemove: () => void;
  onOpenInsert: () => void;
}) {
  const m = slot.module!;
  return (
    <div data-source="src/regions/daily-plan/Timeline.tsx:182:4" className="rounded-[20px] border border-[#4A7BA6]/30 bg-[#4A7BA6]/5 p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
      <div data-source="src/regions/daily-plan/Timeline.tsx:183:6" className="flex items-start justify-between gap-2">
        <div data-source="src/regions/daily-plan/Timeline.tsx:184:8" className="flex items-center gap-3">
          <div data-source="src/regions/daily-plan/Timeline.tsx:185:10" className="flex size-10 items-center justify-center rounded-full bg-[#4A7BA6]/10">
            <TrainFront data-source="src/regions/daily-plan/Timeline.tsx:186:12" strokeWidth={1.75} className="size-5 text-[#4A7BA6]" />
          </div>
          <div data-source="src/regions/daily-plan/Timeline.tsx:188:10">
            <h4 data-source="src/regions/daily-plan/Timeline.tsx:189:12" className="text-base font-semibold text-foreground">{m.name}</h4>
            {m.transportInfo && <p data-source="src/regions/daily-plan/Timeline.tsx:190:32" className="text-sm text-[#4A7BA6]">{m.transportInfo}</p>}
          </div>
        </div>
        <VerifyChip data-source="src/regions/daily-plan/Timeline.tsx:193:8" status={m.verify} />
      </div>

      <div data-source="src/regions/daily-plan/Timeline.tsx:196:6" className="mt-3 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
        <span data-source="src/regions/daily-plan/Timeline.tsx:197:8" className="inline-flex items-center gap-1">
          <Clock data-source="src/regions/daily-plan/Timeline.tsx:198:10" strokeWidth={1.75} className="size-3.5" />
          行程约 {formatStay(m.stayMinutes)}
        </span>
        {m.price > 0 && <span data-source="src/regions/daily-plan/Timeline.tsx:201:24" className="font-semibold text-foreground">¥{m.price}/人</span>}
      </div>

      {m.reason && <p data-source="src/regions/daily-plan/Timeline.tsx:204:19" className="mt-2 text-sm text-muted-foreground">{m.reason}</p>}
      {m.address ? (
        <p data-source="src/regions/daily-plan/Timeline.tsx:206:8" className="mt-1.5 text-xs text-muted-foreground">{m.address}</p>
      ) : (
        <p data-source="src/regions/daily-plan/Timeline.tsx:208:8" className="mt-1.5 text-xs text-primary">地址待确认，无法精确计算路线</p>
      )}
      <p data-source="src/regions/daily-plan/Timeline.tsx:210:6" className="mt-1.5 text-xs text-muted-foreground">来源：{m.source}</p>
      {m.risk && (
        <div data-source="src/regions/daily-plan/Timeline.tsx:212:8" className="mt-2 flex items-start gap-1 rounded-xl bg-primary/10 px-2.5 py-1.5 text-xs text-primary">
          <AlertCircle data-source="src/regions/daily-plan/Timeline.tsx:213:10" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
          <span data-source="src/regions/daily-plan/Timeline.tsx:214:10">{m.risk}</span>
        </div>
      )}

      <div data-source="src/regions/daily-plan/Timeline.tsx:218:6" className="mt-3 flex items-center gap-2">
        <button data-source="src/regions/daily-plan/Timeline.tsx:219:8"
          type="button"
          onClick={onOpenInsert}
          className="inline-flex items-center gap-1 rounded-full bg-card px-3 py-1.5 text-xs font-medium text-foreground transition hover:brightness-95 active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        >
          <Replace data-source="src/regions/daily-plan/Timeline.tsx:224:10" strokeWidth={1.75} className="size-3.5" />
          替换
        </button>
        <button data-source="src/regions/daily-plan/Timeline.tsx:227:8"
          type="button"
          onClick={onRemove}
          className="inline-flex items-center gap-1 rounded-full bg-card px-3 py-1.5 text-xs font-medium text-muted-foreground transition hover:text-primary active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        >
          <Trash2 data-source="src/regions/daily-plan/Timeline.tsx:232:10" strokeWidth={1.75} className="size-3.5" />
          删除
        </button>
      </div>
    </div>
  );
}

function EmptySlot({ onOpenInsert }: { onOpenInsert: () => void }) {
  return (
    <button data-source="src/regions/daily-plan/Timeline.tsx:242:4"
      type="button"
      onClick={onOpenInsert}
      className="flex w-full items-center justify-center gap-2 rounded-[20px] border-2 border-dashed border-border bg-card/50 py-6 text-sm font-medium text-muted-foreground transition hover:border-primary/50 hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
    >
      <Plus data-source="src/regions/daily-plan/Timeline.tsx:247:6" strokeWidth={1.75} className="size-4" />
      插入
    </button>
  );
}
