import { useMemo, useState } from 'react';
import {
  Car,
  Train,
  MapPin,
  Calendar,
  Users,
  Sparkles,
  Wallet,
  Check,
  ArrowRight,
  Loader2,
} from 'lucide-react';
import type { TripConfig, TransportMode } from '../../contracts';
import { cn } from './cn';

interface TripInputProps {
  onStart: (config: TripConfig) => void;
}

const HERO_IMG =
  'https://images.pexels.com/photos/1591373/pexels-photo-1591373.jpeg?auto=compress&cs=tinysrgb&w=1600';

const DESTINATION_CHIPS = ['大理', '西藏', '成都', '厦门', '西安', '青海湖'];

const COMPANION_OPTIONS = ['独自出发', '情侣同行', '家庭亲子', '三五好友', '带娃出游'];

const INTEREST_OPTIONS = [
  '自然风光',
  '人文历史',
  '美食探店',
  '悠闲慢游',
  '户外徒步',
  '拍照打卡',
  '小众冷门',
  '亲子友好',
];

const TRANSPORT_CARDS: { mode: TransportMode; label: string; desc: string; Icon: typeof Car }[] = [
  { mode: 'drive', label: '自驾', desc: '灵活自由，随走随停', Icon: Car },
  { mode: 'transit', label: '公共交通', desc: '高铁地铁，省心省力', Icon: Train },
];

const BUDGET_MIN = 500;
const BUDGET_MAX = 20000;

function diffDays(start: string, end: string): number {
  if (!start || !end) return 0;
  const s = new Date(start).getTime();
  const e = new Date(end).getTime();
  if (Number.isNaN(s) || Number.isNaN(e) || e < s) return 0;
  return Math.floor((e - s) / 86400000) + 1;
}

export function TripInput({ onStart }: TripInputProps) {
  const [destination, setDestination] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [manualDays, setManualDays] = useState('');
  const [transport, setTransport] = useState<TransportMode | null>(null);
  const [companions, setCompanions] = useState<string[]>([]);
  const [interests, setInterests] = useState<string[]>([]);
  const [budgetLow, setBudgetLow] = useState(2000);
  const [budgetHigh, setBudgetHigh] = useState(8000);
  const [loading, setLoading] = useState(false);

  const [errors, setErrors] = useState<{
    destination?: string;
    date?: string;
    transport?: string;
  }>({});

  const autoDays = useMemo(() => diffDays(startDate, endDate), [startDate, endDate]);

  const effectiveDays = useMemo(() => {
    const manual = parseInt(manualDays, 10);
    if (!Number.isNaN(manual) && manual > 0) return manual;
    if (autoDays > 0) return autoDays;
    return 3;
  }, [manualDays, autoDays]);

  const toggle = (list: string[], value: string): string[] =>
    list.includes(value) ? list.filter((v) => v !== value) : [...list, value];

  function validate(): boolean {
    const next: typeof errors = {};
    if (!destination.trim()) next.destination = '请填写想去的目的地';
    if (!startDate || !endDate) {
      next.date = '请选择出发与结束日期';
    } else if (new Date(endDate).getTime() < new Date(startDate).getTime()) {
      next.date = '结束日期不能早于出发日期';
    }
    if (!transport) next.transport = '请选择一种交通方式';
    setErrors(next);
    return Object.keys(next).length === 0;
  }

  function handleStart() {
    if (loading) return;
    if (!validate()) return;
    setLoading(true);
    const low = Math.min(budgetLow, budgetHigh);
    const high = Math.max(budgetLow, budgetHigh);
    const config: TripConfig = {
      destination: destination.trim(),
      startDate,
      endDate,
      days: effectiveDays,
      transport: transport as TransportMode,
      companions: companions.join('、'),
      interests,
      budgetRange: [low, high],
    };
    window.setTimeout(() => {
      setLoading(false);
      onStart(config);
    }, 900);
  }

  return (
    <div data-source="src/regions/trip-input/index.tsx:121:4" className="min-h-screen bg-background text-foreground font-[PingFang_SC,'Noto_Sans_SC',sans-serif]">
      {/* Hero */}
      <section data-source="src/regions/trip-input/index.tsx:123:6" className="relative w-full overflow-hidden">
        <div data-source="src/regions/trip-input/index.tsx:124:8" className="relative h-[62vh] min-h-[420px] w-full">
          <img data-source="src/regions/trip-input/index.tsx:125:10"
            src={HERO_IMG}
            alt="风景"
            className="h-full w-full object-cover"
          />
          <div data-source="src/regions/trip-input/index.tsx:130:10" className="absolute inset-0 bg-gradient-to-t from-foreground/70 via-foreground/20 to-transparent" />
          <div data-source="src/regions/trip-input/index.tsx:131:10" className="absolute inset-x-0 bottom-0 mx-auto max-w-3xl px-6 pb-12">
            <p data-source="src/regions/trip-input/index.tsx:132:12" className="mb-3 text-sm font-medium tracking-wide text-primary-foreground/90">
              轻松规划 · 治愈出发
            </p>
            <h1 data-source="src/regions/trip-input/index.tsx:135:12" className="text-4xl font-bold tracking-tight text-primary-foreground sm:text-5xl md:text-6xl">
              去哪里，都由你定
            </h1>
            <p data-source="src/regions/trip-input/index.tsx:138:12" className="mt-4 max-w-xl text-base text-primary-foreground/85">
              不用赶行程，也不用做攻略。告诉我们几个小心愿，剩下的慢慢来。
            </p>
          </div>
        </div>
      </section>

      {/* Single column form */}
      <main data-source="src/regions/trip-input/index.tsx:146:6" className="mx-auto -mt-8 max-w-2xl px-4 pb-24 sm:px-6">
        <div data-source="src/regions/trip-input/index.tsx:147:8" className="space-y-6">
          {/* Destination */}
          <section data-source="src/regions/trip-input/index.tsx:149:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:150:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <MapPin data-source="src/regions/trip-input/index.tsx:151:14" size={20} strokeWidth={1.75} className="text-primary" />
              想去哪里？
            </label>
            <div data-source="src/regions/trip-input/index.tsx:154:12" className="relative">
              <input data-source="src/regions/trip-input/index.tsx:155:14"
                value={destination}
                onChange={(e) => setDestination(e.target.value)}
                placeholder="输入目的地"
                className="w-full rounded-xl border border-border bg-background px-4 py-3 text-base outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              />
            </div>
            <div data-source="src/regions/trip-input/index.tsx:162:12" className="mt-3 flex flex-wrap gap-2">
              {DESTINATION_CHIPS.map((d) => {
                const active = destination.trim() === d;
                return (
                  <button data-source="src/regions/trip-input/index.tsx:166:18"
                    key={d}
                    type="button"
                    onClick={() => setDestination(d)}
                    className={cn(
                      'rounded-full px-3.5 py-1.5 text-sm transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'bg-primary text-primary-foreground'
                        : 'bg-muted text-muted-foreground hover:text-foreground',
                    )}
                  >
                    {d}
                  </button>
                );
              })}
            </div>
            {errors.destination && (
              <p data-source="src/regions/trip-input/index.tsx:183:14" className="mt-2 text-sm text-primary">{errors.destination}</p>
            )}
          </section>

          {/* Dates + days */}
          <section data-source="src/regions/trip-input/index.tsx:188:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:189:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <Calendar data-source="src/regions/trip-input/index.tsx:190:14" size={20} strokeWidth={1.75} className="text-primary" />
              什么时候出发？
            </label>
            <div data-source="src/regions/trip-input/index.tsx:193:12" className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <div data-source="src/regions/trip-input/index.tsx:194:14">
                <span data-source="src/regions/trip-input/index.tsx:195:16" className="mb-1.5 block text-xs uppercase tracking-wide text-muted-foreground">
                  出发日期
                </span>
                <input data-source="src/regions/trip-input/index.tsx:198:16"
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className="w-full rounded-xl border border-border bg-background px-4 py-3 text-base outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                />
              </div>
              <div data-source="src/regions/trip-input/index.tsx:205:14">
                <span data-source="src/regions/trip-input/index.tsx:206:16" className="mb-1.5 block text-xs uppercase tracking-wide text-muted-foreground">
                  结束日期
                </span>
                <input data-source="src/regions/trip-input/index.tsx:209:16"
                  type="date"
                  value={endDate}
                  min={startDate || undefined}
                  onChange={(e) => setEndDate(e.target.value)}
                  className="w-full rounded-xl border border-border bg-background px-4 py-3 text-base outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                />
              </div>
            </div>
            <div data-source="src/regions/trip-input/index.tsx:218:12" className="mt-3 flex items-center justify-between rounded-xl bg-muted px-4 py-3">
              <span data-source="src/regions/trip-input/index.tsx:219:14" className="text-sm text-muted-foreground">
                {autoDays > 0 ? `按日期计算 ${autoDays} 天` : '也可以手动填天数'}
              </span>
              <div data-source="src/regions/trip-input/index.tsx:222:14" className="flex items-center gap-2">
                <input data-source="src/regions/trip-input/index.tsx:223:16"
                  type="number"
                  min={1}
                  value={manualDays}
                  onChange={(e) => setManualDays(e.target.value)}
                  placeholder={autoDays > 0 ? String(autoDays) : '3'}
                  className="w-20 rounded-lg border border-border bg-card px-3 py-2 text-center text-sm outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                />
                <span data-source="src/regions/trip-input/index.tsx:231:16" className="text-sm text-muted-foreground">天</span>
              </div>
            </div>
            {errors.date && <p data-source="src/regions/trip-input/index.tsx:234:28" className="mt-2 text-sm text-primary">{errors.date}</p>}
          </section>

          {/* Transport */}
          <section data-source="src/regions/trip-input/index.tsx:238:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:239:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <Car data-source="src/regions/trip-input/index.tsx:240:14" size={20} strokeWidth={1.75} className="text-primary" />
              怎么去？
            </label>
            <div data-source="src/regions/trip-input/index.tsx:243:12" className="grid grid-cols-2 gap-3">
              {TRANSPORT_CARDS.map(({ mode, label, desc, Icon }) => {
                const active = transport === mode;
                return (
                  <button data-source="src/regions/trip-input/index.tsx:247:18"
                    key={mode}
                    type="button"
                    onClick={() => setTransport(mode)}
                    className={cn(
                      'relative flex flex-col items-start gap-2 rounded-xl border-2 p-4 text-left transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'border-primary bg-primary/5'
                        : 'border-border bg-card hover:border-muted-foreground/40',
                    )}
                  >
                    {active && (
                      <span data-source="src/regions/trip-input/index.tsx:259:22" className="absolute right-3 top-3 flex size-5 items-center justify-center rounded-full bg-primary text-primary-foreground">
                        <Check data-source="src/regions/trip-input/index.tsx:260:24" size={14} strokeWidth={1.75} />
                      </span>
                    )}
                    <Icon data-source="src/regions/trip-input/index.tsx:263:20"
                      size={24}
                      strokeWidth={1.75}
                      className={active ? 'text-primary' : 'text-muted-foreground'}
                    />
                    <span data-source="src/regions/trip-input/index.tsx:268:20" className="text-base font-semibold">{label}</span>
                    <span data-source="src/regions/trip-input/index.tsx:269:20" className="text-xs text-muted-foreground">{desc}</span>
                  </button>
                );
              })}
            </div>
            {errors.transport && (
              <p data-source="src/regions/trip-input/index.tsx:275:14" className="mt-2 text-sm text-primary">{errors.transport}</p>
            )}
          </section>

          {/* Companions */}
          <section data-source="src/regions/trip-input/index.tsx:280:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:281:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <Users data-source="src/regions/trip-input/index.tsx:282:14" size={20} strokeWidth={1.75} className="text-primary" />
              和谁一起？
            </label>
            <div data-source="src/regions/trip-input/index.tsx:285:12" className="flex flex-wrap gap-2">
              {COMPANION_OPTIONS.map((c) => {
                const active = companions.includes(c);
                return (
                  <button data-source="src/regions/trip-input/index.tsx:289:18"
                    key={c}
                    type="button"
                    onClick={() => setCompanions((prev) => toggle(prev, c))}
                    className={cn(
                      'rounded-full px-3.5 py-1.5 text-sm transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'bg-primary text-primary-foreground'
                        : 'bg-muted text-muted-foreground hover:text-foreground',
                    )}
                  >
                    {c}
                  </button>
                );
              })}
            </div>
          </section>

          {/* Interests */}
          <section data-source="src/regions/trip-input/index.tsx:308:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:309:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <Sparkles data-source="src/regions/trip-input/index.tsx:310:14" size={20} strokeWidth={1.75} className="text-primary" />
              偏好些什么？
            </label>
            <div data-source="src/regions/trip-input/index.tsx:313:12" className="flex flex-wrap gap-2">
              {INTEREST_OPTIONS.map((t) => {
                const active = interests.includes(t);
                return (
                  <button data-source="src/regions/trip-input/index.tsx:317:18"
                    key={t}
                    type="button"
                    onClick={() => setInterests((prev) => toggle(prev, t))}
                    className={cn(
                      'rounded-full px-3.5 py-1.5 text-sm transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'bg-primary text-primary-foreground'
                        : 'bg-muted text-muted-foreground hover:text-foreground',
                    )}
                  >
                    {t}
                  </button>
                );
              })}
            </div>
          </section>

          {/* Budget */}
          <section data-source="src/regions/trip-input/index.tsx:336:10" className="rounded-[20px] border border-border bg-card p-5 transition hover:-translate-y-0.5 hover:shadow-lg">
            <label data-source="src/regions/trip-input/index.tsx:337:12" className="mb-3 flex items-center gap-2 text-base font-semibold">
              <Wallet data-source="src/regions/trip-input/index.tsx:338:14" size={20} strokeWidth={1.75} className="text-primary" />
              人均预算
            </label>
            <div data-source="src/regions/trip-input/index.tsx:341:12" className="mb-4 flex items-baseline justify-between">
              <span data-source="src/regions/trip-input/index.tsx:342:14" className="text-2xl font-bold tracking-tight text-primary">
                ¥{Math.min(budgetLow, budgetHigh).toLocaleString()}
                <span data-source="src/regions/trip-input/index.tsx:344:16" className="mx-1 text-muted-foreground">–</span>¥
                {Math.max(budgetLow, budgetHigh).toLocaleString()}
              </span>
            </div>
            <div data-source="src/regions/trip-input/index.tsx:348:12" className="grid grid-cols-2 gap-3">
              <div data-source="src/regions/trip-input/index.tsx:349:14">
                <span data-source="src/regions/trip-input/index.tsx:350:16" className="mb-1.5 block text-xs uppercase tracking-wide text-muted-foreground">
                  最低
                </span>
                <input data-source="src/regions/trip-input/index.tsx:353:16"
                  type="number"
                  min={BUDGET_MIN}
                  max={BUDGET_MAX}
                  step={100}
                  value={budgetLow}
                  onChange={(e) => setBudgetLow(Number(e.target.value) || 0)}
                  className="w-full rounded-xl border border-border bg-background px-4 py-3 text-base outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                />
              </div>
              <div data-source="src/regions/trip-input/index.tsx:363:14">
                <span data-source="src/regions/trip-input/index.tsx:364:16" className="mb-1.5 block text-xs uppercase tracking-wide text-muted-foreground">
                  最高
                </span>
                <input data-source="src/regions/trip-input/index.tsx:367:16"
                  type="number"
                  min={BUDGET_MIN}
                  max={BUDGET_MAX}
                  step={100}
                  value={budgetHigh}
                  onChange={(e) => setBudgetHigh(Number(e.target.value) || 0)}
                  className="w-full rounded-xl border border-border bg-background px-4 py-3 text-base outline-none transition focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                />
              </div>
            </div>
            <div data-source="src/regions/trip-input/index.tsx:378:12" className="mt-4 space-y-3">
              <div data-source="src/regions/trip-input/index.tsx:379:14">
                <span data-source="src/regions/trip-input/index.tsx:380:16" className="mb-1 block text-xs text-muted-foreground">最低 ¥{budgetLow.toLocaleString()}</span>
                <input data-source="src/regions/trip-input/index.tsx:381:16"
                  type="range"
                  min={BUDGET_MIN}
                  max={BUDGET_MAX}
                  step={100}
                  value={budgetLow}
                  onChange={(e) => setBudgetLow(Number(e.target.value))}
                  className="w-full accent-primary"
                />
              </div>
              <div data-source="src/regions/trip-input/index.tsx:391:14">
                <span data-source="src/regions/trip-input/index.tsx:392:16" className="mb-1 block text-xs text-muted-foreground">最高 ¥{budgetHigh.toLocaleString()}</span>
                <input data-source="src/regions/trip-input/index.tsx:393:16"
                  type="range"
                  min={BUDGET_MIN}
                  max={BUDGET_MAX}
                  step={100}
                  value={budgetHigh}
                  onChange={(e) => setBudgetHigh(Number(e.target.value))}
                  className="w-full accent-primary"
                />
              </div>
            </div>
          </section>

          {/* CTA */}
          <button data-source="src/regions/trip-input/index.tsx:407:10"
            type="button"
            onClick={handleStart}
            disabled={loading}
            className="flex h-12 w-full items-center justify-center gap-2 rounded-full bg-primary px-6 font-semibold text-primary-foreground transition hover:brightness-105 active:scale-[.98] focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-80"
          >
            {loading ? (
              <>
                <Loader2 data-source="src/regions/trip-input/index.tsx:415:16" size={20} strokeWidth={1.75} className="animate-spin" />
                正在生成行程…
              </>
            ) : (
              <>
                开始规划
                <ArrowRight data-source="src/regions/trip-input/index.tsx:421:16" size={20} strokeWidth={1.75} />
              </>
            )}
          </button>
          <p data-source="src/regions/trip-input/index.tsx:425:10" className="text-center text-xs text-muted-foreground">
            预计生成 {effectiveDays} 天行程 · 随时可调整
          </p>
        </div>
      </main>
    </div>
  );
}
