import { useState } from 'react';
import { CheckCircle, CircleAlert, Wallet } from 'lucide-react';
import type { BudgetSummary } from '../../contracts';

function money(n: number) {
  return '¥' + n.toLocaleString('zh-CN');
}

interface BudgetOverviewProps {
  budget: BudgetSummary;
}

export function BudgetOverview({ budget }: BudgetOverviewProps) {
  // Local override to simulate a different budget baseline (demo the over-budget state).
  const [simulateOver, setSimulateOver] = useState(false);

  const effectiveLimit = simulateOver ? Math.max(Math.round(budget.total * 0.82), 1) : budget.limit;
  const overBudget = budget.total > effectiveLimit;
  const ratio = effectiveLimit > 0 ? budget.total / effectiveLimit : 0;
  const barPct = Math.min(Math.round(ratio * 100), 100);
  const overAmount = Math.max(budget.total - effectiveLimit, 0);

  return (
    <section data-source="src/regions/budget-export/BudgetOverview.tsx:24:4" className="bg-card rounded-[20px] border border-border p-6 sm:p-8">
      <div data-source="src/regions/budget-export/BudgetOverview.tsx:25:6" className="flex flex-wrap items-start justify-between gap-4">
        <div data-source="src/regions/budget-export/BudgetOverview.tsx:26:8">
          <div data-source="src/regions/budget-export/BudgetOverview.tsx:27:10" className="flex items-center gap-2 text-muted-foreground">
            <Wallet data-source="src/regions/budget-export/BudgetOverview.tsx:28:12" size={18} strokeWidth={1.75} />
            <span data-source="src/regions/budget-export/BudgetOverview.tsx:29:12" className="text-xs uppercase tracking-wide">总预算</span>
          </div>
          <p data-source="src/regions/budget-export/BudgetOverview.tsx:31:10" className="mt-2 text-5xl sm:text-6xl font-bold tracking-tight text-foreground">
            {money(budget.total)}
          </p>
          <p data-source="src/regions/budget-export/BudgetOverview.tsx:34:10" className="mt-2 text-sm text-muted-foreground">
            预算上限 <span data-source="src/regions/budget-export/BudgetOverview.tsx:35:17" className="font-semibold text-foreground">{money(effectiveLimit)}</span>
          </p>
        </div>

        {overBudget ? (
          <span data-source="src/regions/budget-export/BudgetOverview.tsx:40:10" className="flex items-center gap-1.5 rounded-full bg-[#E8845B]/10 px-3 py-1.5 text-sm font-semibold text-primary">
            <CircleAlert data-source="src/regions/budget-export/BudgetOverview.tsx:41:12" size={16} strokeWidth={1.75} />
            超出预算
          </span>
        ) : (
          <span data-source="src/regions/budget-export/BudgetOverview.tsx:45:10" className="flex items-center gap-1.5 rounded-full bg-[#5C8A6B]/10 px-3 py-1.5 text-sm font-semibold text-[#5C8A6B]">
            <CheckCircle data-source="src/regions/budget-export/BudgetOverview.tsx:46:12" size={16} strokeWidth={1.75} />
            预算正常
          </span>
        )}
      </div>

      {/* limit comparison progress bar */}
      <div data-source="src/regions/budget-export/BudgetOverview.tsx:53:6" className="mt-6">
        <div data-source="src/regions/budget-export/BudgetOverview.tsx:54:8" className="flex items-center justify-between text-xs text-muted-foreground">
          <span data-source="src/regions/budget-export/BudgetOverview.tsx:55:10">已规划花费占上限</span>
          <span data-source="src/regions/budget-export/BudgetOverview.tsx:56:10" className="font-semibold text-foreground">{Math.round(ratio * 100)}%</span>
        </div>
        <div data-source="src/regions/budget-export/BudgetOverview.tsx:58:8" className="mt-2 h-3 w-full overflow-hidden rounded-full bg-muted">
          <div data-source="src/regions/budget-export/BudgetOverview.tsx:59:10"
            className={`h-full rounded-full transition-all duration-500 ${
              overBudget ? 'bg-primary' : 'bg-[#5C8A6B]'
            }`}
            style={{ width: `${barPct}%` }}
          />
        </div>
      </div>

      {/* over-budget hint bar */}
      {overBudget && (
        <div data-source="src/regions/budget-export/BudgetOverview.tsx:70:8" className="mt-4 flex items-start gap-2.5 rounded-xl border border-[#E8845B]/30 bg-[#E8845B]/10 p-3.5 text-sm text-foreground">
          <CircleAlert data-source="src/regions/budget-export/BudgetOverview.tsx:71:10" size={18} strokeWidth={1.75} className="mt-0.5 shrink-0 text-primary" />
          <p data-source="src/regions/budget-export/BudgetOverview.tsx:72:10">
            当前花费{simulateOver ? '（模拟基线）' : ''}已超出上限约{' '}
            <span data-source="src/regions/budget-export/BudgetOverview.tsx:74:12" className="font-semibold text-primary">
              {money(overAmount)}
            </span>
            ，建议下调住宿档次或精简门票行程。
          </p>
        </div>
      )}

      <div data-source="src/regions/budget-export/BudgetOverview.tsx:82:6" className="mt-5">
        <button data-source="src/regions/budget-export/BudgetOverview.tsx:83:8"
          type="button"
          onClick={() => setSimulateOver((v) => !v)}
          className="inline-flex items-center gap-2 rounded-full bg-secondary px-5 h-11 text-sm font-semibold text-secondary-foreground hover:brightness-105 active:scale-[.98] transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        >
          模拟不同预算基线
          <span data-source="src/regions/budget-export/BudgetOverview.tsx:89:10" className="text-xs text-muted-foreground">
            {simulateOver ? '当前：超标态' : '当前：实际态'}
          </span>
        </button>
      </div>
    </section>
  );
}
