import { CheckCircle, Clock } from 'lucide-react';
import type { ContentModule, VerifyStatus } from '../../contracts';

export function cn(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ');
}

export function VerifyChip({ status }: { status: VerifyStatus }) {
  if (status === 'verified') {
    return (
      <span data-source="src/regions/daily-plan/ui.tsx:11:6" className="inline-flex items-center gap-1 rounded-full text-xs px-2.5 py-1 text-[#5C8A6B] bg-[#5C8A6B]/10">
        <CheckCircle data-source="src/regions/daily-plan/ui.tsx:12:8" strokeWidth={1.75} className="size-3.5" />
        已核验
      </span>
    );
  }
  return (
    <span data-source="src/regions/daily-plan/ui.tsx:18:4" className="inline-flex items-center gap-1 rounded-full text-xs px-2.5 py-1 text-muted-foreground bg-muted">
      <Clock data-source="src/regions/daily-plan/ui.tsx:19:6" strokeWidth={1.75} className="size-3.5" />
      待核验
    </span>
  );
}

export function CategoryBadge({ label }: { label: string }) {
  return (
    <span data-source="src/regions/daily-plan/ui.tsx:27:4" className="inline-flex items-center rounded-full text-xs px-2.5 py-1 text-[#4A7BA6] bg-[#4A7BA6]/10">
      {label}
    </span>
  );
}

export function formatStay(minutes: number): string {
  if (minutes <= 0) return '—';
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (h && m) return `${h}h${m}m`;
  if (h) return `${h}h`;
  return `${m}m`;
}

