import { Car, BedDouble, Utensils, Ticket } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { BudgetItem } from '../../contracts';

const CATEGORY_META: Record<
  BudgetItem['category'],
  { icon: LucideIcon; fallbackLabel: string; barColor: string; iconBg: string; iconColor: string }
> = {
  transport: {
    icon: Car,
    fallbackLabel: '交通',
    barColor: 'bg-primary',
    iconBg: 'bg-primary/10',
    iconColor: 'text-primary',
  },
  hotel: {
    icon: BedDouble,
    fallbackLabel: '住宿',
    barColor: 'bg-accent',
    iconBg: 'bg-accent/10',
    iconColor: 'text-accent',
  },
  food: {
    icon: Utensils,
    fallbackLabel: '餐饮',
    barColor: 'bg-primary',
    iconBg: 'bg-primary/10',
    iconColor: 'text-primary',
  },
  ticket: {
    icon: Ticket,
    fallbackLabel: '门票',
    barColor: 'bg-accent',
    iconBg: 'bg-accent/10',
    iconColor: 'text-accent',
  },
};

const ORDER: BudgetItem['category'][] = ['transport', 'hotel', 'food', 'ticket'];

function money(n: number) {
  return '¥' + n.toLocaleString('zh-CN');
}

interface CategoryBreakdownProps {
  items: BudgetItem[];
  total: number;
}

export function CategoryBreakdown({ items, total }: CategoryBreakdownProps) {
  // Keep a stable transport/hotel/food/ticket order; use provided items when present.
  const byCategory = new Map<BudgetItem['category'], BudgetItem>();
  items.forEach((it) => byCategory.set(it.category, it));

  const cards = ORDER.map((cat) => {
    const meta = CATEGORY_META[cat];
    const item = byCategory.get(cat);
    const amount = item?.amount ?? 0;
    const label = item?.label ?? meta.fallbackLabel;
    const pct = total > 0 ? Math.round((amount / total) * 100) : 0;
    return { cat, meta, amount, label, pct };
  });

  return (
    <section data-source="src/regions/budget-export/CategoryBreakdown.tsx:65:4" className="bg-card rounded-[20px] border border-border p-5">
      <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:66:6" className="flex items-baseline justify-between gap-3">
        <h2 data-source="src/regions/budget-export/CategoryBreakdown.tsx:67:8" className="text-lg font-bold tracking-tight text-foreground">分项花费拆分</h2>
        <span data-source="src/regions/budget-export/CategoryBreakdown.tsx:68:8" className="text-xs text-muted-foreground">按四大类别核算</span>
      </div>

      <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:71:6" className="mt-5 grid grid-cols-1 sm:grid-cols-2 gap-4">
        {cards.map(({ cat, meta, amount, label, pct }) => {
          const Icon = meta.icon;
          return (
            <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:75:12"
              key={cat}
              className="rounded-xl border border-border bg-card p-4 hover:shadow-lg hover:-translate-y-0.5 transition"
            >
              <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:79:14" className="flex items-center gap-3">
                <span data-source="src/regions/budget-export/CategoryBreakdown.tsx:80:16"
                  className={`flex size-10 items-center justify-center rounded-full ${meta.iconBg} ${meta.iconColor}`}
                >
                  <Icon data-source="src/regions/budget-export/CategoryBreakdown.tsx:83:18" size={20} strokeWidth={1.75} />
                </span>
                <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:85:16" className="min-w-0">
                  <p data-source="src/regions/budget-export/CategoryBreakdown.tsx:86:18" className="text-sm font-semibold text-foreground truncate">{label}</p>
                  <p data-source="src/regions/budget-export/CategoryBreakdown.tsx:87:18" className="text-xs text-muted-foreground">占总额 {pct}%</p>
                </div>
                <p data-source="src/regions/budget-export/CategoryBreakdown.tsx:89:16" className="ml-auto text-lg font-bold tracking-tight text-foreground">
                  {money(amount)}
                </p>
              </div>

              <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:94:14" className="mt-3 h-2 w-full overflow-hidden rounded-full bg-muted">
                <div data-source="src/regions/budget-export/CategoryBreakdown.tsx:95:16"
                  className={`h-full rounded-full ${meta.barColor} transition-all duration-500`}
                  style={{ width: `${pct}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}
