import { useMemo, useState } from 'react';
import * as Dialog from '@radix-ui/react-dialog';
import { Search, X, MapPin, Clock, AlertCircle, Plus } from 'lucide-react';
import type { ContentModule, ModuleCategory } from '../../contracts';
import {
  CANDIDATE_POOL,
  CATEGORY_LABELS,
  cloneCandidateForInsert,
  type Candidate,
} from './mock';
import { cn, VerifyChip, CategoryBadge, formatStay } from './ui';

type FilterCat = Exclude<ModuleCategory, 'transport'>;

interface InsertDrawerProps {
  open: boolean;
  slotLabel: string;
  onClose: () => void;
  onInsert: (mod: ContentModule) => void;
}

const FILTERS: Array<{ key: FilterCat; label: string }> = [
  { key: 'scenery', label: CATEGORY_LABELS.scenery },
  { key: 'shop', label: CATEGORY_LABELS.shop },
  { key: 'activity', label: CATEGORY_LABELS.activity },
  { key: 'food', label: CATEGORY_LABELS.food },
];

export function InsertDrawer({ open, slotLabel, onClose, onInsert }: InsertDrawerProps) {
  const [query, setQuery] = useState('');
  const [cat, setCat] = useState<FilterCat | 'all'>('all');
  const [loading, setLoading] = useState(false);

  const results = useMemo(() => {
    const q = query.trim();
    return CANDIDATE_POOL.filter((c) => {
      if (cat !== 'all' && c.category !== cat) return false;
      if (!q) return true;
      return c.name.includes(q) || c.reason.includes(q) || c.address.includes(q);
    });
  }, [query, cat]);

  function runSearch(value: string) {
    setQuery(value);
    setLoading(true);
    window.setTimeout(() => setLoading(false), 480);
  }

  function handleInsert(c: Candidate) {
    onInsert(cloneCandidateForInsert(c));
    onClose();
  }

  return (
    <Dialog.Root data-source="src/regions/daily-plan/InsertDrawer.tsx:55:4" open={open} onOpenChange={(o) => !o && onClose()}>
      <Dialog.Portal data-source="src/regions/daily-plan/InsertDrawer.tsx:56:6">
        <Dialog.Overlay data-source="src/regions/daily-plan/InsertDrawer.tsx:57:8" className="fixed inset-0 z-40 bg-foreground/40 backdrop-blur-sm data-[state=open]:animate-in data-[state=open]:fade-in" />
        <Dialog.Content data-source="src/regions/daily-plan/InsertDrawer.tsx:58:8"
          className="fixed inset-x-0 bottom-0 z-50 max-h-[85vh] overflow-hidden rounded-t-[20px] bg-card border-t border-border shadow-2xl focus:outline-none"
          aria-describedby={undefined}
        >
          <div data-source="src/regions/daily-plan/InsertDrawer.tsx:62:10" className="mx-auto flex h-full max-w-3xl flex-col">
            <div data-source="src/regions/daily-plan/InsertDrawer.tsx:63:12" className="flex items-start justify-between gap-4 px-6 pt-5">
              <div data-source="src/regions/daily-plan/InsertDrawer.tsx:64:14">
                <Dialog.Title data-source="src/regions/daily-plan/InsertDrawer.tsx:65:16" className="text-xl font-bold tracking-tight text-foreground">
                  为「{slotLabel}」挑选一个地点
                </Dialog.Title>
                <p data-source="src/regions/daily-plan/InsertDrawer.tsx:68:16" className="mt-1 text-sm text-muted-foreground">搜索并选择候选，插入到当前时段。</p>
              </div>
              <Dialog.Close data-source="src/regions/daily-plan/InsertDrawer.tsx:70:14" asChild>
                <button data-source="src/regions/daily-plan/InsertDrawer.tsx:71:16"
                  type="button"
                  onClick={onClose}
                  aria-label="关闭"
                  className="rounded-full p-2 text-muted-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 transition"
                >
                  <X data-source="src/regions/daily-plan/InsertDrawer.tsx:77:18" strokeWidth={1.75} className="size-5" />
                </button>
              </Dialog.Close>
            </div>

            <div data-source="src/regions/daily-plan/InsertDrawer.tsx:82:12" className="px-6 pt-4">
              <div data-source="src/regions/daily-plan/InsertDrawer.tsx:83:14" className="relative">
                <Search data-source="src/regions/daily-plan/InsertDrawer.tsx:84:16" strokeWidth={1.75} className="pointer-events-none absolute left-4 top-1/2 size-5 -translate-y-1/2 text-muted-foreground" />
                <input data-source="src/regions/daily-plan/InsertDrawer.tsx:85:16"
                  value={query}
                  onChange={(e) => runSearch(e.target.value)}
                  placeholder="搜索景点、餐厅、玩乐项目…"
                  className="w-full rounded-full border border-border bg-background py-3 pl-12 pr-4 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 transition"
                />
              </div>

              <div data-source="src/regions/daily-plan/InsertDrawer.tsx:93:14" className="mt-3 flex flex-wrap items-center gap-2">
                <FilterPill data-source="src/regions/daily-plan/InsertDrawer.tsx:94:16" active={cat === 'all'} label="全部" onClick={() => setCat('all')} />
                {FILTERS.map((f) => (
                  <FilterPill data-source="src/regions/daily-plan/InsertDrawer.tsx:96:18"
                    key={f.key}
                    active={cat === f.key}
                    label={f.label}
                    onClick={() => setCat(f.key)}
                  />
                ))}
              </div>
            </div>

            <div data-source="src/regions/daily-plan/InsertDrawer.tsx:106:12" className="mt-4 flex-1 overflow-y-auto px-6 pb-6">
              {loading ? (
                <SkeletonList data-source="src/regions/daily-plan/InsertDrawer.tsx:108:16" />
              ) : results.length === 0 ? (
                <EmptyState data-source="src/regions/daily-plan/InsertDrawer.tsx:110:16" query={query} />
              ) : (
                <div data-source="src/regions/daily-plan/InsertDrawer.tsx:112:16" className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  {results.map((c) => (
                    <CandidateCard data-source="src/regions/daily-plan/InsertDrawer.tsx:114:20" key={c.id} candidate={c} onInsert={() => handleInsert(c)} />
                  ))}
                </div>
              )}
            </div>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function FilterPill({ active, label, onClick }: { active: boolean; label: string; onClick: () => void }) {
  return (
    <button data-source="src/regions/daily-plan/InsertDrawer.tsx:128:4"
      type="button"
      onClick={onClick}
      className={cn(
        'rounded-full px-4 py-1.5 text-sm font-medium transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
        active
          ? 'bg-primary text-primary-foreground'
          : 'bg-muted text-muted-foreground hover:text-foreground',
      )}
    >
      {label}
    </button>
  );
}

function CandidateCard({ candidate, onInsert }: { candidate: Candidate; onInsert: () => void }) {
  return (
    <div data-source="src/regions/daily-plan/InsertDrawer.tsx:145:4" className="flex flex-col rounded-[20px] border border-border bg-card p-4 transition hover:-translate-y-0.5 hover:shadow-lg">
      {candidate.image && (
        <div data-source="src/regions/daily-plan/InsertDrawer.tsx:147:8" className="mb-3 aspect-[16/10] overflow-hidden rounded-[16px]">
          <img data-source="src/regions/daily-plan/InsertDrawer.tsx:148:10" src={candidate.image} alt={candidate.name} className="size-full object-cover" />
        </div>
      )}
      <div data-source="src/regions/daily-plan/InsertDrawer.tsx:151:6" className="flex items-start justify-between gap-2">
        <h4 data-source="src/regions/daily-plan/InsertDrawer.tsx:152:8" className="text-base font-semibold text-foreground">{candidate.name}</h4>
        <VerifyChip data-source="src/regions/daily-plan/InsertDrawer.tsx:153:8" status={candidate.verify} />
      </div>
      <div data-source="src/regions/daily-plan/InsertDrawer.tsx:155:6" className="mt-2 flex flex-wrap items-center gap-2">
        <CategoryBadge data-source="src/regions/daily-plan/InsertDrawer.tsx:156:8" label={CATEGORY_LABELS[candidate.category as FilterCat] ?? candidate.category} />
        <span data-source="src/regions/daily-plan/InsertDrawer.tsx:157:8" className="inline-flex items-center gap-1 text-xs text-muted-foreground">
          <Clock data-source="src/regions/daily-plan/InsertDrawer.tsx:158:10" strokeWidth={1.75} className="size-3.5" />
          建议 {formatStay(candidate.stayMinutes)}
        </span>
      </div>
      <p data-source="src/regions/daily-plan/InsertDrawer.tsx:162:6" className="mt-2 line-clamp-2 text-sm text-muted-foreground">{candidate.reason}</p>

      <div data-source="src/regions/daily-plan/InsertDrawer.tsx:164:6" className="mt-2 flex items-start gap-1 text-xs text-muted-foreground">
        <MapPin data-source="src/regions/daily-plan/InsertDrawer.tsx:165:8" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
        {candidate.address ? (
          <span data-source="src/regions/daily-plan/InsertDrawer.tsx:167:10">{candidate.address}</span>
        ) : (
          <span data-source="src/regions/daily-plan/InsertDrawer.tsx:169:10" className="text-primary">地址待确认，无法精确计算路线</span>
        )}
      </div>

      <p data-source="src/regions/daily-plan/InsertDrawer.tsx:173:6" className="mt-1.5 text-xs text-muted-foreground">来源：{candidate.source}</p>
      {candidate.risk && (
        <div data-source="src/regions/daily-plan/InsertDrawer.tsx:175:8" className="mt-2 flex items-start gap-1 rounded-xl bg-primary/10 px-2.5 py-1.5 text-xs text-primary">
          <AlertCircle data-source="src/regions/daily-plan/InsertDrawer.tsx:176:10" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
          <span data-source="src/regions/daily-plan/InsertDrawer.tsx:177:10">{candidate.risk}</span>
        </div>
      )}

      <div data-source="src/regions/daily-plan/InsertDrawer.tsx:181:6" className="mt-3 flex items-center justify-between">
        <span data-source="src/regions/daily-plan/InsertDrawer.tsx:182:8" className="text-sm font-semibold text-foreground">
          {candidate.price > 0 ? `¥${candidate.price}/人` : '免费'}
        </span>
        <button data-source="src/regions/daily-plan/InsertDrawer.tsx:185:8"
          type="button"
          onClick={onInsert}
          className="inline-flex items-center gap-1 rounded-full bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition hover:brightness-105 active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        >
          <Plus data-source="src/regions/daily-plan/InsertDrawer.tsx:190:10" strokeWidth={1.75} className="size-4" />
          插入到此时段
        </button>
      </div>
    </div>
  );
}

function SkeletonList() {
  return (
    <div data-source="src/regions/daily-plan/InsertDrawer.tsx:200:4" className="grid grid-cols-1 gap-4 sm:grid-cols-2">
      {[0, 1, 2, 3].map((i) => (
        <div data-source="src/regions/daily-plan/InsertDrawer.tsx:202:8" key={i} className="rounded-[20px] border border-border bg-card p-4">
          <div data-source="src/regions/daily-plan/InsertDrawer.tsx:203:10" className="mb-3 aspect-[16/10] animate-pulse rounded-[16px] bg-muted" />
          <div data-source="src/regions/daily-plan/InsertDrawer.tsx:204:10" className="h-4 w-2/3 animate-pulse rounded-full bg-muted" />
          <div data-source="src/regions/daily-plan/InsertDrawer.tsx:205:10" className="mt-2 h-3 w-1/2 animate-pulse rounded-full bg-muted" />
          <div data-source="src/regions/daily-plan/InsertDrawer.tsx:206:10" className="mt-3 h-3 w-full animate-pulse rounded-full bg-muted" />
        </div>
      ))}
    </div>
  );
}

function EmptyState({ query }: { query: string }) {
  return (
    <div data-source="src/regions/daily-plan/InsertDrawer.tsx:215:4" className="flex flex-col items-center justify-center py-16 text-center">
      <div data-source="src/regions/daily-plan/InsertDrawer.tsx:216:6" className="flex size-14 items-center justify-center rounded-full bg-muted">
        <Search data-source="src/regions/daily-plan/InsertDrawer.tsx:217:8" strokeWidth={1.75} className="size-6 text-muted-foreground" />
      </div>
      <p data-source="src/regions/daily-plan/InsertDrawer.tsx:219:6" className="mt-4 text-base font-semibold text-foreground">没有找到「{query}」相关的地点</p>
      <p data-source="src/regions/daily-plan/InsertDrawer.tsx:220:6" className="mt-1 text-sm text-muted-foreground">换个关键词，或切换分类再试试。</p>
    </div>
  );
}
