import { useState, useEffect } from 'react';
import { Sparkles, PencilRuler, CalendarDays, MapPin, Check } from 'lucide-react';
import type {
  DailyPlanRegionProps,
  PlanMode,
  Slot,
  ContentModule,
  Hotel,
} from '../../contracts';
import { cn } from './ui';
import { Timeline } from './Timeline';
import { Sidebar } from './Sidebar';
import { InsertDrawer } from './InsertDrawer';
import { HotelDialog } from './HotelDialog';

const MODE_TABS: Array<{ key: PlanMode; label: string; desc: string; icon: typeof Sparkles }> = [
  { key: 'ai', label: 'AI 自动生成', desc: '一键生成顺路行程', icon: Sparkles },
  { key: 'scratch', label: '从零搭建', desc: '自己掌控每个时段', icon: PencilRuler },
];

export function DailyPlan({
  config,
  plan,
  mode,
  hotel,
  budget,
  onModeChange,
  onInsertModule,
  onRemoveModule,
  onSelectHotel,
  onGoBudget,
}: DailyPlanRegionProps) {
  const [activeDay, setActiveDay] = useState(0);
  const [insertSlot, setInsertSlot] = useState<Slot | null>(null);
  const [hotelOpen, setHotelOpen] = useState(false);
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => {
    if (activeDay > plan.length - 1) setActiveDay(0);
  }, [plan.length, activeDay]);

  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(null), 2200);
    return () => window.clearTimeout(t);
  }, [toast]);

  const day = plan[activeDay];

  function handleInsert(mod: ContentModule) {
    if (!insertSlot) return;
    onInsertModule(activeDay, insertSlot.id, mod);
    setToast('已插入到行程');
  }

  function handleSelectHotel(h: Hotel) {
    onSelectHotel(h);
    setHotelOpen(false);
    setToast('酒店已更新');
  }

  return (
    <div data-source="src/regions/daily-plan/index.tsx:63:4" className="min-h-screen bg-background text-foreground">
      <div data-source="src/regions/daily-plan/index.tsx:64:6" className="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
        {/* 顶部：模式切换 + 概览 */}
        <header data-source="src/regions/daily-plan/index.tsx:66:8" className="mb-8">
          <div data-source="src/regions/daily-plan/index.tsx:67:10" className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between">
            <div data-source="src/regions/daily-plan/index.tsx:68:12">
              <p data-source="src/regions/daily-plan/index.tsx:69:14" className="text-sm font-medium text-[#4A7BA6]">动态计划工作台</p>
              <h1 data-source="src/regions/daily-plan/index.tsx:70:14" className="mt-1 text-4xl font-bold tracking-tight sm:text-5xl">
                {config.destination}
                <span data-source="src/regions/daily-plan/index.tsx:72:16" className="text-muted-foreground"> · {config.days} 天行程</span>
              </h1>
              <div data-source="src/regions/daily-plan/index.tsx:74:14" className="mt-3 flex flex-wrap items-center gap-4 text-sm text-muted-foreground">
                <span data-source="src/regions/daily-plan/index.tsx:75:16" className="inline-flex items-center gap-1.5">
                  <CalendarDays data-source="src/regions/daily-plan/index.tsx:76:18" strokeWidth={1.75} className="size-4" />
                  {config.startDate} – {config.endDate}
                </span>
                <span data-source="src/regions/daily-plan/index.tsx:79:16" className="inline-flex items-center gap-1.5">
                  <MapPin data-source="src/regions/daily-plan/index.tsx:80:18" strokeWidth={1.75} className="size-4" />
                  {config.companions}
                </span>
              </div>
            </div>

            {/* 模式切换 tab */}
            <div data-source="src/regions/daily-plan/index.tsx:87:12" className="inline-flex gap-2 rounded-full border border-border bg-card p-1.5">
              {MODE_TABS.map((t) => {
                const active = mode === t.key;
                const Icon = t.icon;
                return (
                  <button data-source="src/regions/daily-plan/index.tsx:92:18"
                    key={t.key}
                    type="button"
                    onClick={() => onModeChange(t.key)}
                    className={cn(
                      'flex items-center gap-2 rounded-full px-4 py-2.5 text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'bg-primary text-primary-foreground'
                        : 'text-muted-foreground hover:text-foreground',
                    )}
                  >
                    <Icon data-source="src/regions/daily-plan/index.tsx:103:20" strokeWidth={1.75} className="size-4" />
                    <span data-source="src/regions/daily-plan/index.tsx:104:20" className="hidden sm:inline">{t.label}</span>
                    <span data-source="src/regions/daily-plan/index.tsx:105:20" className="sm:hidden">{t.key === 'ai' ? 'AI' : '自建'}</span>
                  </button>
                );
              })}
            </div>
          </div>
        </header>

        <div data-source="src/regions/daily-plan/index.tsx:113:8" className="grid grid-cols-1 gap-8 lg:grid-cols-[1fr_340px]">
          {/* 左主区 */}
          <main data-source="src/regions/daily-plan/index.tsx:115:10">
            {/* Day tabs */}
            <div data-source="src/regions/daily-plan/index.tsx:117:12" className="mb-6 flex flex-wrap gap-2">
              {plan.map((d, i) => {
                const active = i === activeDay;
                return (
                  <button data-source="src/regions/daily-plan/index.tsx:121:18"
                    key={d.dayIndex}
                    type="button"
                    onClick={() => setActiveDay(i)}
                    className={cn(
                      'flex flex-col items-start rounded-[16px] border px-4 py-2.5 text-left transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      active
                        ? 'border-primary bg-primary/5'
                        : 'border-border bg-card hover:-translate-y-0.5 hover:shadow-lg',
                    )}
                  >
                    <span data-source="src/regions/daily-plan/index.tsx:132:20"
                      className={cn(
                        'text-sm font-semibold',
                        active ? 'text-primary' : 'text-foreground',
                      )}
                    >
                      Day {d.dayIndex + 1}
                    </span>
                    <span data-source="src/regions/daily-plan/index.tsx:140:20" className="text-xs text-muted-foreground">
                      {d.dateLabel} · {d.cityLabel}
                    </span>
                  </button>
                );
              })}
            </div>

            {day ? (
              <div data-source="src/regions/daily-plan/index.tsx:149:14" className="rounded-[20px] border border-border bg-card p-5 sm:p-6">
                <div data-source="src/regions/daily-plan/index.tsx:150:16" className="mb-5 flex items-center justify-between">
                  <div data-source="src/regions/daily-plan/index.tsx:151:18">
                    <h2 data-source="src/regions/daily-plan/index.tsx:152:20" className="text-2xl font-bold tracking-tight">Day {day.dayIndex + 1} · {day.cityLabel}</h2>
                    <p data-source="src/regions/daily-plan/index.tsx:153:20" className="mt-0.5 text-sm text-muted-foreground">{day.dateLabel}</p>
                  </div>
                </div>
                <Timeline data-source="src/regions/daily-plan/index.tsx:156:16"
                  day={day}
                  dayIdx={activeDay}
                  onRemove={(slotId) => {
                    onRemoveModule(activeDay, slotId);
                    setToast('已从行程中移除');
                  }}
                  onOpenInsert={(slot) => setInsertSlot(slot)}
                />
              </div>
            ) : (
              <div data-source="src/regions/daily-plan/index.tsx:167:14" className="rounded-[20px] border border-dashed border-border bg-card p-12 text-center text-sm text-muted-foreground">
                暂无行程数据。
              </div>
            )}
          </main>

          {/* 右侧栏 */}
          <Sidebar data-source="src/regions/daily-plan/index.tsx:174:10"
            hotel={hotel}
            budget={budget}
            onOpenHotel={() => setHotelOpen(true)}
            onGoBudget={onGoBudget}
            onShare={() => setToast('行程链接已复制，快去分享吧')}
          />
        </div>
      </div>

      {/* 插入抽屉 */}
      <InsertDrawer data-source="src/regions/daily-plan/index.tsx:185:6"
        open={!!insertSlot}
        slotLabel={insertSlot?.label ?? ''}
        onClose={() => setInsertSlot(null)}
        onInsert={handleInsert}
      />

      {/* 酒店 Dialog */}
      <HotelDialog data-source="src/regions/daily-plan/index.tsx:193:6"
        open={hotelOpen}
        current={hotel}
        onClose={() => setHotelOpen(false)}
        onSelect={handleSelectHotel}
      />

      {/* Toast */}
      {toast && (
        <div data-source="src/regions/daily-plan/index.tsx:202:8" className="fixed bottom-6 left-1/2 z-[60] -translate-x-1/2">
          <div data-source="src/regions/daily-plan/index.tsx:203:10" className="flex items-center gap-2 rounded-full bg-foreground px-5 py-3 text-sm font-medium text-background shadow-2xl">
            <Check data-source="src/regions/daily-plan/index.tsx:204:12" strokeWidth={1.75} className="size-4 text-primary" />
            {toast}
          </div>
        </div>
      )}
    </div>
  );
}
