import { useMemo, useState } from 'react';
import * as Dialog from '@radix-ui/react-dialog';
import { Search, X, MapPin, Star, Check } from 'lucide-react';
import type { Hotel } from '../../contracts';
import { HOTEL_OPTIONS } from './mock';
import { cn } from './ui';

interface HotelDialogProps {
  open: boolean;
  current: Hotel | null;
  onClose: () => void;
  onSelect: (h: Hotel) => void;
}

export function HotelDialog({ open, current, onClose, onSelect }: HotelDialogProps) {
  const [query, setQuery] = useState('');

  const results = useMemo(() => {
    const q = query.trim();
    if (!q) return HOTEL_OPTIONS;
    return HOTEL_OPTIONS.filter((h) => h.name.includes(q) || h.address.includes(q));
  }, [query]);

  return (
    <Dialog.Root data-source="src/regions/daily-plan/HotelDialog.tsx:25:4" open={open} onOpenChange={(o) => !o && onClose()}>
      <Dialog.Portal data-source="src/regions/daily-plan/HotelDialog.tsx:26:6">
        <Dialog.Overlay data-source="src/regions/daily-plan/HotelDialog.tsx:27:8" className="fixed inset-0 z-40 bg-foreground/40 backdrop-blur-sm" />
        <Dialog.Content data-source="src/regions/daily-plan/HotelDialog.tsx:28:8"
          className="fixed left-1/2 top-1/2 z-50 w-[92vw] max-w-2xl max-h-[85vh] -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-[20px] border border-border bg-card shadow-2xl focus:outline-none"
          aria-describedby={undefined}
        >
          <div data-source="src/regions/daily-plan/HotelDialog.tsx:32:10" className="flex items-start justify-between gap-4 px-6 pt-5">
            <div data-source="src/regions/daily-plan/HotelDialog.tsx:33:12">
              <Dialog.Title data-source="src/regions/daily-plan/HotelDialog.tsx:34:14" className="text-xl font-bold tracking-tight text-foreground">
                选择你的酒店锚点
              </Dialog.Title>
              <p data-source="src/regions/daily-plan/HotelDialog.tsx:37:14" className="mt-1 text-sm text-muted-foreground">对比价格、位置与便利度，选一个最合适的落脚点。</p>
            </div>
            <Dialog.Close data-source="src/regions/daily-plan/HotelDialog.tsx:39:12" asChild>
              <button data-source="src/regions/daily-plan/HotelDialog.tsx:40:14"
                type="button"
                onClick={onClose}
                aria-label="关闭"
                className="rounded-full p-2 text-muted-foreground hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 transition"
              >
                <X data-source="src/regions/daily-plan/HotelDialog.tsx:46:16" strokeWidth={1.75} className="size-5" />
              </button>
            </Dialog.Close>
          </div>

          <div data-source="src/regions/daily-plan/HotelDialog.tsx:51:10" className="px-6 pt-4">
            <div data-source="src/regions/daily-plan/HotelDialog.tsx:52:12" className="relative">
              <Search data-source="src/regions/daily-plan/HotelDialog.tsx:53:14" strokeWidth={1.75} className="pointer-events-none absolute left-4 top-1/2 size-5 -translate-y-1/2 text-muted-foreground" />
              <input data-source="src/regions/daily-plan/HotelDialog.tsx:54:14"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="搜索酒店名称或地址…"
                className="w-full rounded-full border border-border bg-background py-3 pl-12 pr-4 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 transition"
              />
            </div>
          </div>

          <div data-source="src/regions/daily-plan/HotelDialog.tsx:63:10" className="mt-4 max-h-[52vh] space-y-4 overflow-y-auto px-6 pb-6">
            {results.length === 0 ? (
              <div data-source="src/regions/daily-plan/HotelDialog.tsx:65:14" className="py-12 text-center text-sm text-muted-foreground">未找到匹配的酒店，换个关键词试试。</div>
            ) : (
              results.map((h) => {
                const active = current?.id === h.id;
                return (
                  <div data-source="src/regions/daily-plan/HotelDialog.tsx:70:18"
                    key={h.id}
                    className={cn(
                      'flex gap-4 rounded-[20px] border bg-card p-4 transition hover:-translate-y-0.5 hover:shadow-lg',
                      active ? 'border-primary ring-2 ring-primary/30' : 'border-border',
                    )}
                  >
                    {h.image && (
                      <div data-source="src/regions/daily-plan/HotelDialog.tsx:78:22" className="hidden w-40 shrink-0 overflow-hidden rounded-[16px] sm:block">
                        <img data-source="src/regions/daily-plan/HotelDialog.tsx:79:24" src={h.image} alt={h.name} className="size-full object-cover" />
                      </div>
                    )}
                    <div data-source="src/regions/daily-plan/HotelDialog.tsx:82:20" className="flex min-w-0 flex-1 flex-col">
                      <div data-source="src/regions/daily-plan/HotelDialog.tsx:83:22" className="flex items-start justify-between gap-2">
                        <h4 data-source="src/regions/daily-plan/HotelDialog.tsx:84:24" className="text-base font-semibold text-foreground">{h.name}</h4>
                        <span data-source="src/regions/daily-plan/HotelDialog.tsx:85:24" className="inline-flex items-center gap-1 text-sm font-semibold text-foreground">
                          <Star data-source="src/regions/daily-plan/HotelDialog.tsx:86:26" strokeWidth={1.75} className="size-4 text-primary" />
                          {(h.score / 10).toFixed(1)}
                        </span>
                      </div>
                      <p data-source="src/regions/daily-plan/HotelDialog.tsx:90:22" className="mt-1 text-sm font-semibold text-primary">{h.priceRange}</p>
                      <div data-source="src/regions/daily-plan/HotelDialog.tsx:91:22" className="mt-1 flex items-start gap-1 text-xs text-muted-foreground">
                        <MapPin data-source="src/regions/daily-plan/HotelDialog.tsx:92:24" strokeWidth={1.75} className="mt-0.5 size-3.5 shrink-0" />
                        <span data-source="src/regions/daily-plan/HotelDialog.tsx:93:24">{h.address}</span>
                      </div>
                      <p data-source="src/regions/daily-plan/HotelDialog.tsx:95:22" className="mt-1.5 text-sm text-muted-foreground">{h.convenience}</p>
                      <div data-source="src/regions/daily-plan/HotelDialog.tsx:96:22" className="mt-3">
                        <button data-source="src/regions/daily-plan/HotelDialog.tsx:97:24"
                          type="button"
                          onClick={() => onSelect(h)}
                          className={cn(
                            'inline-flex items-center gap-1 rounded-full px-4 py-2 text-sm font-semibold transition active:scale-[.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                            active
                              ? 'bg-[#5C8A6B]/10 text-[#5C8A6B]'
                              : 'bg-primary text-primary-foreground hover:brightness-105',
                          )}
                        >
                          {active ? (
                            <>
                              <Check data-source="src/regions/daily-plan/HotelDialog.tsx:109:30" strokeWidth={1.75} className="size-4" />
                              当前所选
                            </>
                          ) : (
                            '选择此酒店'
                          )}
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
