const fillAiSlots = (prefix: string): Slot[] => emptySlots(prefix).map((slot) => {
  if (slot.type === 'intercity') return slot;
  const template = AI_SLOT_TEMPLATES[slot.type];
  return template ? { ...slot, module: { ...template, id: `${prefix}-${slot.type}-module` }, routeFromPrev: '步行或短途打车 · 约 10–20 分钟' } : slot;
});

const day2Slots: Slot[] = fillAiSlots('d2');
