export function computeBudget(overBudget = false): BudgetSummary {
  const items: BudgetSummary['items'] = [
    { category: 'transport', label: '交通', amount: overBudget ? 1680 : 1180 },
    { category: 'hotel', label: '住宿', amount: overBudget ? 2760 : 1680 },
    { category: 'food', label: '餐饮', amount: 1240 },
    { category: 'ticket', label: '门票 / 体验', amount: 860 },
  ];
  const total = items.reduce((s, i) => s + i.amount, 0);
  const limit = 5000;
  return { total, limit, overBudget: total > limit, items };
}
